"""Validate GenUP category-preference data generated by TripMind."""
from __future__ import annotations

import argparse
import json
import sys
from collections import Counter, defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from tripmind.processing.genup import parse_target_poi_id


def rows(path: Path):
    with path.open(encoding="utf-8") as stream:
        for line in stream:
            if line.strip():
                yield json.loads(line)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", default="data/processed/genup_preference")
    args = parser.parse_args()
    root = Path(args.root)
    manifest = json.loads((root / "manifest.json").read_text(encoding="utf-8"))

    if manifest.get("candidate_semantics") != "category_only":
        raise AssertionError("unexpected candidate semantics")
    if manifest.get("supports_same_category_ranking") is not False:
        raise AssertionError("manifest must explicitly disable same-category ranking")
    expected = int(manifest["negatives_per_positive"])

    context_ids = set()
    counts = Counter()
    positives = defaultdict(set)
    records = []

    for path in sorted(root.glob("*.jsonl")):
        for record in rows(path):
            if record.get("task") != "category_preference_ranking":
                raise AssertionError("unexpected task")
            context_id = record["context_id"]
            if context_id in context_ids:
                raise AssertionError(f"duplicate context_id: {context_id}")
            context_ids.add(context_id)
            positive = record["positive_candidate"]["poi_id"]
            if not record["positive_candidate"].get("category"):
                raise AssertionError("positive candidate lacks category")
            if parse_target_poi_id(record["target_text"]) != positive:
                raise AssertionError("positive disagrees with target")
            positives[(record["source_dataset"], record["user_key"])].add(positive)
            records.append(record)
            counts[record["split"]] += 1

    if not context_ids:
        raise AssertionError("no preference contexts found")

    negative_types = Counter()
    for record in records:
        positive = record["positive_candidate"]
        positive_id = positive["poi_id"]
        positive_category_id = positive.get("category_id")
        history = set(record.get("history_poi_ids", []))
        negatives = record["negative_candidates"]
        if len(negatives) != expected:
            raise AssertionError("wrong negative count")
        negative_ids = [candidate["poi_id"] for candidate in negatives]
        if len(set(negative_ids)) != len(negative_ids):
            raise AssertionError("duplicate negative")
        if positive_id in negative_ids or any(x in history for x in negative_ids):
            raise AssertionError("positive/history used as negative")
        key = (record["source_dataset"], record["user_key"])
        if any(x in positives[key] for x in negative_ids):
            raise AssertionError("known target used as negative")

        for candidate in negatives:
            if not candidate.get("category"):
                raise AssertionError("negative lacks category")
            if candidate.get("negative_type") != "sampled_unobserved_different_category":
                raise AssertionError("invalid negative type")
            if positive_category_id and candidate.get("category_id") == positive_category_id:
                raise AssertionError("same-category negative in category-only task")
            negative_types[candidate["negative_type"]] += 1

    print("VALIDATED")
    print("task: sampled cross-category category-preference ranking")
    print("same-category ranking supported: False")
    print("contexts:", len(context_ids))
    print("splits:", dict(counts))
    print("negative_types:", dict(negative_types))


if __name__ == "__main__":
    main()
